1	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
2	import 'package:flutter_test/flutter_test.dart';
3	import 'package:fpdart/fpdart.dart';
4	import 'package:local_auth/local_auth.dart';
5	import 'package:mocktail/mocktail.dart';
6	
7	import 'package:cerne/core/failure/failure.dart';
8	import 'package:cerne/features/vault/data/repositories/vault_repository_impl.dart';
9	import 'package:cerne/features/vault/domain/entities/vault_status.dart';
10	
11	class MockLocalAuthentication extends Mock implements LocalAuthentication {}
12	
13	class MockFlutterSecureStorage extends Mock implements FlutterSecureStorage {}
14	
15	/// Covers spec-2-1's I/O & Edge-Case Matrix exactly:
16	/// - biometrics succeed -> `unlocked` emitted, `Right(unit)`.
17	/// - biometrics fail/cancelled/unavailable (`false` or a thrown
18	///   `LocalAuthException`) -> status stays `locked`,
19	///   `Left(Failure.malformedResponse(...))`, no crash.
20	///
21	/// Plus spec-2-2's own additions:
22	/// - `submitPin`, no PIN stored yet -> stores it, `unlocked`, `Right(unit)`.
23	/// - `submitPin`, stored PIN matches -> `unlocked`, `Right(unit)`.
24	/// - `submitPin`, stored PIN mismatch -> stays `locked`,
25	///   `Left(Failure.malformedResponse(...))`, no attempt cap.
26	void main() {
27	  late MockLocalAuthentication mockLocalAuthentication;
28	  late MockFlutterSecureStorage mockSecureStorage;
29	  late VaultRepositoryImpl repository;
30	
31	  setUp(() {
32	    mockLocalAuthentication = MockLocalAuthentication();
33	    mockSecureStorage = MockFlutterSecureStorage();
34	    repository = VaultRepositoryImpl(
35	      localAuthentication: mockLocalAuthentication,
36	      secureStorage: mockSecureStorage,
37	    );
38	  });
39	
40	  /// Same rationale as `session_repository_impl_test.dart`'s own
41	  /// `emittedDuring` helper, with one difference: unlike
42	  /// `SessionRepository.statusStream` (nullable, no replay until the first
43	  /// emission), [VaultRepository.statusStream] always synchronously
44	  /// replays the current (never-null) [VaultStatus] to a brand-new
45	  /// listener — so the first element this helper's subscription ever sees
46	  /// is always that initial replay, not an emission caused by [act]. It's
47	  /// drained and discarded here so the returned list reflects only
48	  /// emissions [act] itself caused.
49	  Future<List<VaultStatus>> emittedDuring(
50	    Future<void> Function() act,
51	  ) async {
52	    final emitted = <VaultStatus>[];
53	    final subscription = repository.statusStream.listen(emitted.add);
54	    await Future<void>.delayed(Duration.zero);
55	    emitted.clear();
56	    await act();
57	    await Future<void>.delayed(Duration.zero);
58	    await subscription.cancel();
59	    return emitted;
60	  }
61	
62	  group('VaultStatus.currentStatus — non-nullable, known at construction', () {
63	    test('currentStatus is VaultStatus.locked before any authenticate() '
64	        'call — no async warm-up, unlike SessionStatus (Design Notes)', () {
65	      expect(repository.currentStatus, VaultStatus.locked);
66	    });
67	
68	    test('a listener that subscribes before any authenticate() call still '
69	        'immediately sees VaultStatus.locked, not nothing until the first '
70	        'emission (Stream.multi replay, mirrors SessionRepositoryImpl)', () async {
71	      final status = await repository.statusStream.first;
72	
73	      expect(status, VaultStatus.locked);
74	    });
75	  });
76	
77	  group('cold start, biometrics succeed', () {
78	    test('authenticate() returns true -> statusStream emits unlocked, '
79	        'currentStatus flips to unlocked, Right(unit) returned', () async {
80	      when(
81	        () => mockLocalAuthentication.authenticate(
82	          localizedReason: any(named: 'localizedReason'),
83	          biometricOnly: any(named: 'biometricOnly'),
84	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
85	        ),
86	      ).thenAnswer((_) async => true);
87	
88	      Either<Failure, Unit>? result;
89	      final emitted = await emittedDuring(() async {
90	        result = await repository.authenticate();
91	      });
92	
93	      expect(emitted, [VaultStatus.unlocked]);
94	      expect(repository.currentStatus, VaultStatus.unlocked);
95	      expect(result!.isRight(), isTrue);
96	    });
97	
98	    test('authenticate() is called with biometricOnly: true — Boundaries: '
99	        '"never set biometricOnly: false" — so the OS\'s own device '
100	        'passcode screen never silently satisfies it', () async {
101	      when(
102	        () => mockLocalAuthentication.authenticate(
103	          localizedReason: any(named: 'localizedReason'),
104	          biometricOnly: any(named: 'biometricOnly'),
105	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
106	        ),
107	      ).thenAnswer((_) async => true);
108	
109	      await repository.authenticate();
110	
111	      verify(
112	        () => mockLocalAuthentication.authenticate(
113	          localizedReason: any(named: 'localizedReason'),
114	          biometricOnly: true,
115	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
116	        ),
117	      ).called(1);
118	    });
119	  });
120	
121	  group('cold start, biometrics fail/cancelled/unavailable', () {
122	    test('authenticate() returns false -> status stays locked, no '
123	        'emission, Left(Failure.malformedResponse), never '
124	        'Failure.authInvalid (Boundaries: reserved for password login)', () async {
125	      when(
126	        () => mockLocalAuthentication.authenticate(
127	          localizedReason: any(named: 'localizedReason'),
128	          biometricOnly: any(named: 'biometricOnly'),
129	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
130	        ),
131	      ).thenAnswer((_) async => false);
132	
133	      Either<Failure, Unit>? result;
134	      final emitted = await emittedDuring(() async {
135	        result = await repository.authenticate();
136	      });
137	
138	      expect(emitted, isEmpty);
139	      expect(repository.currentStatus, VaultStatus.locked);
140	      expect(result!.isLeft(), isTrue);
141	      result!.match(
142	        (failure) => expect(failure, isA<MalformedResponse>()),
143	        (_) => fail('expected Left'),
144	      );
145	    });
146	
147	    test('authenticate() throws LocalAuthException (e.g. user cancelled) '
148	        '-> status stays locked, no emission, Left(Failure.'
149	        'malformedResponse), no crash (RNF09: never let a platform '
150	        'exception escape unmapped)', () async {
151	      when(
152	        () => mockLocalAuthentication.authenticate(
153	          localizedReason: any(named: 'localizedReason'),
154	          biometricOnly: any(named: 'biometricOnly'),
155	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
156	        ),
157	      ).thenThrow(
158	        const LocalAuthException(code: LocalAuthExceptionCode.userCanceled),
159	      );
160	
161	      Either<Failure, Unit>? result;
162	      final emitted = await emittedDuring(() async {
163	        result = await repository.authenticate();
164	      });
165	
166	      expect(emitted, isEmpty);
167	      expect(repository.currentStatus, VaultStatus.locked);
168	      expect(result!.isLeft(), isTrue);
169	      result!.match(
170	        (failure) => expect(failure, isA<MalformedResponse>()),
171	        (_) => fail('expected Left'),
172	      );
173	    });
174	
175	    test('authenticate() throws LocalAuthException with an OS-lockout '
176	        'code (biometricLockout) -> same fail-closed outcome as any '
177	        'other LocalAuthException, no code-specific branch (AC2: no '
178	        'second biometric-retry affordance, always routes to the PIN '
179	        'fallback)', () async {
180	      when(
181	        () => mockLocalAuthentication.authenticate(
182	          localizedReason: any(named: 'localizedReason'),
183	          biometricOnly: any(named: 'biometricOnly'),
184	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
185	        ),
186	      ).thenThrow(
187	        const LocalAuthException(
188	          code: LocalAuthExceptionCode.biometricLockout,
189	        ),
190	      );
191	
192	      final result = await repository.authenticate();
193	
194	      expect(repository.currentStatus, VaultStatus.locked);
195	      expect(result.isLeft(), isTrue);
196	      result.match(
197	        (failure) => expect(failure, isA<MalformedResponse>()),
198	        (_) => fail('expected Left'),
199	      );
200	    });
201	
202	    test('authenticate() throws LocalAuthException for no enrolled '
203	        'biometrics -> same fail-closed outcome as any other '
204	        'LocalAuthException', () async {
205	      when(
206	        () => mockLocalAuthentication.authenticate(
207	          localizedReason: any(named: 'localizedReason'),
208	          biometricOnly: any(named: 'biometricOnly'),
209	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
210	        ),
211	      ).thenThrow(
212	        const LocalAuthException(
213	          code: LocalAuthExceptionCode.noBiometricsEnrolled,
214	        ),
215	      );
216	
217	      final result = await repository.authenticate();
218	
219	      expect(repository.currentStatus, VaultStatus.locked);
220	      expect(result.isLeft(), isTrue);
221	    });
222	
223	    test('authenticate() throws a plain (non-LocalAuthException) '
224	        'exception (e.g. the plugin channel itself failing) -> same '
225	        'fail-closed outcome, Left(Failure.malformedResponse), no crash '
226	        '(RNF09: never let a platform exception escape unmapped)', () async {
227	      when(
228	        () => mockLocalAuthentication.authenticate(
229	          localizedReason: any(named: 'localizedReason'),
230	          biometricOnly: any(named: 'biometricOnly'),
231	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
232	        ),
233	      ).thenThrow(Exception('plugin channel failed'));
234	
235	      final result = await repository.authenticate();
236	
237	      expect(repository.currentStatus, VaultStatus.locked);
238	      expect(result.isLeft(), isTrue);
239	    });
240	  });
241	
242	  group('submitPin() — spec-2-2', () {
243	    test('no PIN stored yet -> stores the submitted PIN, statusStream '
244	        'emits unlocked, currentStatus flips to unlocked, Right(unit) '
245	        'returned (no PIN-creation screen exists anywhere in '
246	        'docs/input/ — Design Notes)', () async {
247	      when(
248	        () => mockSecureStorage.read(key: any(named: 'key')),
249	      ).thenAnswer((_) async => null);
250	      when(
251	        () => mockSecureStorage.write(
252	          key: any(named: 'key'),
253	          value: any(named: 'value'),
254	        ),
255	      ).thenAnswer((_) async {});
256	
257	      Either<Failure, Unit>? result;
258	      final emitted = await emittedDuring(() async {
259	        result = await repository.submitPin('1234');
260	      });
261	
262	      verify(
263	        () => mockSecureStorage.write(key: 'vault_pin', value: '1234'),
264	      ).called(1);
265	      expect(emitted, [VaultStatus.unlocked]);
266	      expect(repository.currentStatus, VaultStatus.unlocked);
267	      expect(result!.isRight(), isTrue);
268	    });
269	
270	    test('stored PIN matches -> statusStream emits unlocked, '
271	        'currentStatus flips to unlocked, Right(unit) returned', () async {
272	      when(
273	        () => mockSecureStorage.read(key: any(named: 'key')),
274	      ).thenAnswer((_) async => '1234');
275	
276	      Either<Failure, Unit>? result;
277	      final emitted = await emittedDuring(() async {
278	        result = await repository.submitPin('1234');
279	      });
280	
281	      verifyNever(
282	        () => mockSecureStorage.write(
283	          key: any(named: 'key'),
284	          value: any(named: 'value'),
285	        ),
286	      );
287	      expect(emitted, [VaultStatus.unlocked]);
288	      expect(repository.currentStatus, VaultStatus.unlocked);
289	      expect(result!.isRight(), isTrue);
290	    });
291	
292	    test('stored PIN mismatch -> status stays locked, no emission, '
293	        'Left(Failure.malformedResponse(...)), never Failure.authInvalid '
294	        '(Boundaries: reserved for password login), no attempt cap — '
295	        'always retryable', () async {
296	      when(
297	        () => mockSecureStorage.read(key: any(named: 'key')),
298	      ).thenAnswer((_) async => '1234');
299	
300	      Either<Failure, Unit>? result;
301	      final emitted = await emittedDuring(() async {
302	        result = await repository.submitPin('9999');
303	      });
304	
305	      expect(emitted, isEmpty);
306	      expect(repository.currentStatus, VaultStatus.locked);
307	      expect(result!.isLeft(), isTrue);
308	      result!.match(
309	        (failure) => expect(failure, isA<MalformedResponse>()),
310	        (_) => fail('expected Left'),
311	      );
312	
313	      // No attempt cap — a second mismatched attempt behaves identically,
314	      // still retryable, never a dead end.
315	      final secondResult = await repository.submitPin('0000');
316	      expect(repository.currentStatus, VaultStatus.locked);
317	      expect(secondResult.isLeft(), isTrue);
318	    });
319	
320	    test('secure-storage throws on read -> Left(Failure.'
321	        'malformedResponse), status stays locked, no crash (RNF09: never '
322	        'let a platform exception escape unmapped)', () async {
323	      when(
324	        () => mockSecureStorage.read(key: any(named: 'key')),
325	      ).thenThrow(Exception('keychain unavailable'));
326	
327	      final result = await repository.submitPin('1234');
328	
329	      expect(repository.currentStatus, VaultStatus.locked);
330	      expect(result.isLeft(), isTrue);
331	    });
332	  });
333	
334	  group('dispose()', () {
335	    test('closes the underlying stream — a subsequent authenticate() '
336	        'success never throws trying to emit on a closed controller '
337	        '(mirrors SessionRepositoryImpl\'s isClosed guard); the attempted '
338	        'emit is a silent no-op, so currentStatus stays at whatever it '
339	        'was before dispose() even though authenticate() itself still '
340	        'resolves Right(unit)', () async {
341	      when(
342	        () => mockLocalAuthentication.authenticate(
343	          localizedReason: any(named: 'localizedReason'),
344	          biometricOnly: any(named: 'biometricOnly'),
345	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
346	        ),
347	      ).thenAnswer((_) async => true);
348	
349	      await repository.dispose();
350	
351	      final result = await repository.authenticate();
352	
353	      expect(result.isRight(), isTrue);
354	      expect(repository.currentStatus, VaultStatus.locked);
355	    });
356	  });
357	}
