73	  /// The last status emitted. Starts at [VaultStatus.locked] — not
74	  /// nullable, see [VaultStatus]'s own doc — so [currentStatus] is correct
75	  /// synchronously from construction, with no async warm-up step.
76	  VaultStatus _lastStatus = VaultStatus.locked;
