143	    try {
144	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
145	      // OS's own device-passcode UI satisfy this call, which would bypass
146	      // Cerne's own PIN screen (Story 2.2) entirely.
147	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
148	      // (e.g. an incoming call) retries on foreground instead of failing
149	      // outright.
150	      final success = await _localAuthentication.authenticate(
151	        localizedReason: 'Autentique-se para acessar o Cerne',
152	        biometricOnly: true,
153	        persistAcrossBackgrounding: true,
154	      );
155	      if (success) {
156	        _emit(VaultStatus.unlocked);
157	        return right(unit);
158	      }
159	      // A `false` result (declined/unavailable, no exception) — status
160	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
161	      // for password login).
162	      return left(
163	        const Failure.malformedResponse(
164	          message: 'Biometric authentication was not successful',
165	        ),
166	      );
167	    } on LocalAuthException catch (error) {
168	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
169	      // etc. (RNF09: never let a platform exception escape unmapped).
170	      return left(Failure.malformedResponse(message: error.toString()));
171	    } catch (error) {
172	      // Any other thrown platform exception (e.g. the plugin's channel
173	      // itself failing) must never escape unmapped either (RNF09) — fail
174	      // closed, same as the documented `LocalAuthException` branch above,
175	      // mirroring `SessionRepositoryImpl.restoreSession()`'s own plain
176	      // `catch`.
177	      return left(Failure.malformedResponse(message: error.toString()));
178	    }
179	  }
