181	  @override
182	  Future<Either<Failure, Unit>> submitPin(String pin) async {
183	    try {
184	      final storedPin = await _secureStorage.read(key: _pinStorageKey);
185	      // No PIN-creation screen exists anywhere in `docs/input/` (Design
186	      // Notes) — the first ever `submitPin` call sets the stored PIN
