198	      // has no attempt cap — always retryable"); never `Failure.authInvalid`
199	      // (reserved for password login), same rationale as `authenticate()`.
200	      return left(
201	        const Failure.malformedResponse(
202	          message: 'PIN did not match the stored PIN',
203	        ),
