205	    } catch (error) {
206	      // A thrown platform exception from the secure-storage channel must
207	      // never escape unmapped either (RNF09) — fail closed, same as
208	      // `authenticate()`'s own plain `catch`.
209	      return left(Failure.malformedResponse(message: error.toString()));
210	    }
